import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"同步控制","link":"/api/SIMD-API/tensor_api/sync/sync"},{"text":"block、intra、inter和subblock同步","link":"/api/SIMD-API/tensor_api/sync/block_sync"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/sync/block_sync.md","filePath":"api/SIMD-API/tensor_api/sync/block_sync.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793173587000}'),l={name:"api/SIMD-API/tensor_api/sync/block_sync.md"};function e(t,s,d,o,i,_){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>block、intra、inter和subblock同步</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>本组接口提供四类到达/等待同步能力：</p><ul><li>block同步：实现单个AI Core内AIC与全部AIV之间的同步。</li><li>intra同步：实现单个AI Core内AIC与单个AIV之间的同步。</li><li>inter同步：实现不同AI Core之间的同步。</li><li>subblock同步：实现单个AI Core内subblock（一个group内的从核）之间的同步。</li></ul><p>每类同步均提供<code>arrive</code>和<code>wait</code>两个接口。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_block_arrive</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_block_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_intra_arrive</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">sync_id</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_intra_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">sync_id</span><span class="p">)</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_inter_arrive</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_inter_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_subblock_arrive</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">sync_subblock_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">pipe</td><td align="left">输入</td><td align="left">同步关联的流水，类型为<code>pipe_t</code>。</td></tr><tr><td align="left">flag_id</td><td align="left">输入</td><td align="left">block、inter或subblock同步标记，用于标识同一组同步信号。取值范围为<code>[0, 15]</code>，每个<code>flag_id</code>各自拥有独立的4位计数器。</td></tr><tr><td align="left">sync_id</td><td align="left">输入</td><td align="left">intra同步标记，用于标识同一组同步信号。每个<code>sync_id</code>各自拥有独立的4位计数器。AIC侧拥有32个<code>sync_id</code>（0~31），每个AIV侧各拥有16个<code>sync_id</code>（0~15）。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p><code>sync_block_arrive</code>与<code>sync_block_wait</code>、<code>sync_inter_arrive</code>与<code>sync_inter_wait</code>、<code>sync_subblock_arrive</code>与<code>sync_subblock_wait</code>配对使用时，<code>flag_id</code>必须完全一致，否则会出现未定义行为。</p></li><li><p><code>sync_intra_arrive</code>与<code>sync_intra_wait</code>配对使用时，不要求二者传入相同的<code>sync_id</code>，而是要求符合以下跨核ID映射关系，否则会出现未定义行为：</p><ul><li>AIV0中<code>sync_intra_arrive</code>的<code>sync_id</code>取值为<code>0~15</code>，分别对应AIC中<code>sync_intra_wait</code>的<code>sync_id</code>取值<code>0~15</code>。</li><li>AIV1中<code>sync_intra_arrive</code>的<code>sync_id</code>取值为<code>0~15</code>，分别对应AIC中<code>sync_intra_wait</code>的<code>sync_id</code>取值<code>16~31</code>。</li><li>AIC中<code>sync_intra_arrive</code>的<code>sync_id</code>取值为<code>0~15</code>，分别对应AIV0中<code>sync_intra_wait</code>的<code>sync_id</code>取值<code>0~15</code>。</li><li>AIC中<code>sync_intra_arrive</code>的<code>sync_id</code>取值为<code>16~31</code>，分别对应AIV1中<code>sync_intra_wait</code>的<code>sync_id</code>取值<code>0~15</code>。</li></ul></li><li><p>核函数不能使用<code>__cube__</code>或<code>__vector__</code>函数执行空间限定符，否则硬件不会开启调度模块，无法正常进行同步。各同步接口支持的函数执行空间限定符如下：</p><table><thead><tr><th align="left">同步接口</th><th align="left">支持的函数执行空间限定符</th></tr></thead><tbody><tr><td align="left"><code>sync_block_arrive</code> / <code>sync_block_wait</code></td><td align="left"><code>__mix__(1, 1)</code>、<code>__mix__(1, 2)</code></td></tr><tr><td align="left"><code>sync_intra_arrive</code> / <code>sync_intra_wait</code></td><td align="left"><code>__mix__(1, 2)</code></td></tr><tr><td align="left"><code>sync_inter_arrive</code> / <code>sync_inter_wait</code></td><td align="left"><code>__mix__(0, 1)</code>、<code>__mix__(1, 0)</code>、<code>__mix__(1, 1)</code>、<code>__mix__(1, 2)</code></td></tr><tr><td align="left"><code>sync_subblock_arrive</code> / <code>sync_subblock_wait</code></td><td align="left"><code>__mix__(1, 1)</code>、<code>__mix__(1, 2)</code></td></tr></tbody></table></li><li><p>各接口支持的<code>pipe</code>取值如下：</p><table><thead><tr><th align="left">同步接口</th><th align="left">AIC支持的<code>pipe</code></th><th align="left">AIV支持的<code>pipe</code></th></tr></thead><tbody><tr><td align="left"><code>sync_block_arrive</code> / <code>sync_inter_arrive</code></td><td align="left"><code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_FIX</code></td><td align="left"><code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr><tr><td align="left"><code>sync_block_wait</code> / <code>sync_inter_wait</code></td><td align="left"><code>PIPE_S</code>、<code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_FIX</code></td><td align="left"><code>PIPE_S</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr><tr><td align="left"><code>sync_intra_arrive</code> / <code>sync_intra_wait</code></td><td align="left"><code>PIPE_S</code>、<code>PIPE_M</code>、<code>PIPE_MTE1</code>、<code>PIPE_MTE2</code>、<code>PIPE_FIX</code></td><td align="left"><code>PIPE_S</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr><tr><td align="left"><code>sync_subblock_arrive</code></td><td align="left">不支持</td><td align="left"><code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr><tr><td align="left"><code>sync_subblock_wait</code></td><td align="left">不支持</td><td align="left"><code>PIPE_S</code>、<code>PIPE_MTE2</code>、<code>PIPE_MTE3</code>、<code>PIPE_V</code></td></tr></tbody></table></li><li><p><code>sync_subblock_arrive</code>和<code>sync_subblock_wait</code>仅支持AIV调用。</p></li><li><p><code>arrive</code>接口不阻塞<code>pipe</code>流水的后续指令；<code>wait</code>接口阻塞<code>pipe</code>流水的后续指令，直到对应计数器非0。计数器非0时，<code>wait</code>接口解除阻塞并将计数器减1。</p></li><li><p><code>sync_block_arrive</code>、<code>sync_block_wait</code>、<code>sync_inter_arrive</code>、<code>sync_inter_wait</code>、<code>sync_subblock_arrive</code>和<code>sync_subblock_wait</code>的<code>flag_id</code>取值范围为<code>[0, 15]</code>，超出范围的值会被按位宽截断处理为低4位。</p></li><li><p><code>sync_intra_arrive</code>和<code>sync_intra_wait</code>中，AIC的<code>sync_id</code>取值范围为<code>[0, 31]</code>，超出范围的值会被按位宽截断处理为低5位；AIV的<code>sync_id</code>取值范围为<code>[0, 15]</code>，超出范围的值会被按位宽截断处理为低4位。</p></li><li><p>每个计数器最多连续累加15次，必须保证计数器的值不超过15，否则触发异常。</p></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例在__mix__(1, 2)核函数中使用block同步：AIV填充UB并将结果写回Global Memory，随后调用sync_block_arrive通知AIC；AIC调用sync_block_wait等待通知后写入Global Memory。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>

<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">sync_flag_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">block_sync_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">data_buffer</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_layout</span><span class="p">(</span><span class="n">make_shape</span><span class="p">(</span><span class="n">total_length</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">data_ub</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">data_buffer</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">output_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">output</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="n">ASC_IS_AIV</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">total_length</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">data_buffer</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0f</span><span class="p">;</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">        </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_ub_to_gm</span><span class="p">{}),</span><span class="w"> </span><span class="n">output_gm</span><span class="p">,</span><span class="w"> </span><span class="n">data_ub</span><span class="p">);</span>
<span class="w">        </span><span class="n">sync_block_arrive</span><span class="p">(</span><span class="n">pipe_t</span><span class="o">::</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">sync_flag_id</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="n">ASC_IS_AIC</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">sync_block_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="o">::</span><span class="n">PIPE_MTE1</span><span class="p">,</span><span class="w"> </span><span class="n">sync_flag_id</span><span class="p">);</span>
<span class="w">        </span><span class="n">output</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0f</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const k=a(l,[["render",e]]);export{w as __pageData,k as default};
